```turtle
@prefix ht:   <http://example.org/onto/hypertension#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

ht: a owl:Ontology ;
    rdfs:label "Hypertension Ontology"@en ;
    rdfs:comment "An ontology modeling the classification, etiology, measurement, treatment, risk factors and target-organ damage of hypertension, derived from clinical corpus passages."@en .

#################################################################
# 1. REIFIED MEASUREMENT AXIS
#################################################################

ht:BloodPressureReading a owl:Class ;
    rdfs:label "Blood Pressure Reading"@en ;
    skos:definition "A measured pair of systolic and diastolic blood pressure values, expressed in millimetres of mercury."@en .

ht:hasSystolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has systolic value"@en ;
    skos:definition "The maximum arterial pressure during one heartbeat, measured in mmHg, associated with a blood pressure reading."@en ;
    rdfs:domain ht:BloodPressureReading ;
    rdfs:range xsd:integer .

ht:hasDiastolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diastolic value"@en ;
    skos:definition "The minimum arterial pressure between heartbeats, measured in mmHg, associated with a blood pressure reading."@en ;
    rdfs:domain ht:BloodPressureReading ;
    rdfs:range xsd:integer .

ht:BloodPressureCategory a owl:Class ;
    rdfs:label "Blood Pressure Category"@en ;
    skos:definition "A classification band (e.g. Normal, Elevated, Stage 1, Stage 2) into which a blood pressure reading falls, under the 2017 ACC/AHA classification scheme."@en ;
    rdfs:subClassOf ht:BloodPressureReading .

ht:hasBloodPressureCategory a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has blood pressure category"@en ;
    skos:definition "Relates a blood pressure reading to the single classification category that its systolic and/or diastolic values realize."@en ;
    rdfs:domain ht:BloodPressureReading ;
    rdfs:range ht:BloodPressureCategory .

ht:NormalBloodPressure a owl:Class ;
    rdfs:label "Normal Blood Pressure"@en ;
    skos:definition "Blood pressure reading with a systolic pressure less than 120 mmHg and a diastolic pressure less than 80 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    rdfs:comment "The European Society of Cardiology (2024) instead places the normal threshold under 120/70 mmHg, using a lower diastolic cut-point than the AHA/ACC under-120/80 mmHg definition used here."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ;
          owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 120 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ;
          owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ]
    ) ] .

ht:ElevatedBloodPressure a owl:Class ;
    rdfs:label "Elevated Blood Pressure"@en ;
    skos:definition "Blood pressure reading with a systolic pressure of 120 to 129 mmHg and a diastolic pressure less than 80 mmHg; previously termed prehypertension under JNC 7."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    rdfs:comment "JNC 7 instead labels the 120-139/80-89 mmHg range 'prehypertension'; the 2024 ESC guideline groups 120-139/70-89 mmHg together as 'Elevated'."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ;
          owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:minInclusive 120 ] [ xsd:maxInclusive 129 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ;
          owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ]
    ) ] .

ht:Stage1Hypertension a owl:Class ;
    rdfs:label "Stage 1 Hypertension"@en ;
    skos:definition "Blood pressure reading with a systolic pressure of 130 to 139 mmHg or a diastolic pressure of 80 to 89 mmHg, per the 2017 ACC/AHA classification."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    rdfs:comment "ESC/ESH and ISH guidelines instead classify this range (130-139/85-89 mmHg) as 'High-normal' rather than as hypertension, diagnosing hypertension only from 140/90 mmHg."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:BloodPressureReading
        [ a owl:Class ; owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ;
              owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 130 ] [ xsd:maxInclusive 139 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ;
              owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 80 ] [ xsd:maxInclusive 89 ] ) ] ]
        ) ]
    ) ] .

ht:Stage2Hypertension a owl:Class ;
    rdfs:label "Stage 2 Hypertension"@en ;
    skos:definition "Blood pressure reading with a systolic pressure of 140 mmHg or greater or a diastolic pressure of 90 mmHg or greater, per the 2017 ACC/AHA classification."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    rdfs:comment "ESC/ESH grade 1 hypertension begins at the same 140/90 mmHg threshold but subdivides higher pressures into grades 1-3, whereas ACC/AHA uses a single Stage 2 category for all readings at or above 140/90 mmHg."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:BloodPressureReading
        [ a owl:Class ; owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ;
              owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 140 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ;
              owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 90 ] ) ] ]
        ) ]
    ) ] .

owl:AllDisjointClasses [ owl:members ( ht:NormalBloodPressure ht:ElevatedBloodPressure ht:Stage1Hypertension ht:Stage2Hypertension ) ] .

#################################################################
# 2. HYPERTENSION (DISEASE) AND SUBTYPES
#################################################################

ht:Hypertension a owl:Class ;
    rdfs:label "Hypertension"@en ;
    skos:altLabel "High Blood Pressure"@en ;
    skos:definition "A chronic medical condition characterized by sustained elevation of arterial blood pressure."@en ;
    rdfs:comment "A documented guideline conflict exists on the diagnostic systolic threshold: the 2017 ACC/AHA guideline diagnoses hypertension at a systolic pressure of 130 mmHg or more, while ESC/ESH, WHO, ISH and JNC guidelines use 140 mmHg or more."@en .

ht:hasDiagnosticSystolicThreshold a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diagnostic systolic threshold"@en ;
    skos:definition "The systolic blood pressure value (mmHg) at or above which a guideline diagnoses hypertension."@en ;
    rdfs:domain ht:Hypertension ;
    rdfs:range xsd:integer ;
    rdfs:comment "Competing values documented in the corpus: 130 mmHg (2017 ACC/AHA) versus 140 mmHg (ESC/ESH, JNC 7, WHO, ISH)."@en .

ht:PrimaryHypertension a owl:Class ;
    rdfs:label "Primary Hypertension"@en ;
    skos:altLabel "Essential Hypertension"@en , "Idiopathic Hypertension"@en ;
    skos:definition "Hypertension with no single identifiable secondary cause, accounting for approximately 85-95% of cases and arising from an interaction of genetic predisposition and environmental factors."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:SecondaryHypertension a owl:Class ;
    rdfs:label "Secondary Hypertension"@en ;
    skos:altLabel "Inessential Hypertension"@en ;
    skos:definition "Hypertension that is secondary to an identifiable underlying cause, accounting for approximately 5-15% of cases in adults."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasSecondaryCause ; owl:someValuesFrom ht:SecondaryCause ]
    ) ] .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryHypertension ht:SecondaryHypertension ) ] .

ht:IsolatedSystolicHypertension a owl:Class ;
    rdfs:label "Isolated Systolic Hypertension"@en ;
    skos:definition "The predominant form of hypertension in older adults, characterized by a disproportionate rise in systolic pressure (above 140 mmHg, or 130 mmHg under 2017 ACC/AHA) with a preserved or low diastolic pressure (below 90 mmHg), producing a widened pulse pressure, and chiefly caused by age-related arterial stiffening."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:WhiteCoatHypertension a owl:Class ;
    rdfs:label "White Coat Hypertension"@en ;
    skos:altLabel "White Coat Syndrome"@en , "White Coat Effect"@en ;
    skos:definition "A form of labile hypertension in which blood pressure is elevated in a clinical setting but normal when measured outside that setting."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:MaskedHypertension a owl:Class ;
    rdfs:label "Masked Hypertension"@en ;
    skos:altLabel "MH"@en ;
    skos:definition "A blood pressure phenotype in which office or clinic measurements are normal but out-of-clinic measurements are elevated, the mirror image of white coat hypertension."@en ;
    rdfs:subClassOf ht:Hypertension .

owl:AllDisjointClasses [ owl:members ( ht:WhiteCoatHypertension ht:MaskedHypertension ) ] .

ht:ResistantHypertension a owl:Class ;
    rdfs:label "Resistant Hypertension"@en ;
    skos:definition "High blood pressure that remains uncontrolled to goal despite adherence to three suitably dosed antihypertensive medications of different classes, one of which is a diuretic, after exclusion of the white coat effect; blood pressure requiring four or more agents is likewise regarded as resistant."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasAntihypertensive ;
          owl:minQualifiedCardinality "3"^^xsd:nonNegativeInteger ; owl:onClass ht:Antihypertensive ]
    ) ] .

ht:HypertensiveCrisis a owl:Class ;
    rdfs:label "Hypertensive Crisis"@en ;
    skos:definition "A severe, acute elevation of blood pressure, conventionally a systolic pressure over 180 mmHg or a diastolic pressure exceeding 120 mmHg, classified according to the presence or absence of acute target-organ damage."@en ;
    rdfs:subClassOf ht:Hypertension ;
    rdfs:comment "The 180/120 mmHg threshold is conventional rather than independently predictive of outcomes."@en .

ht:HypertensiveUrgency a owl:Class ;
    rdfs:label "Hypertensive Urgency"@en ;
    skos:definition "A hypertensive crisis without evidence of acute target-organ damage, typically managed with gradual oral blood pressure reduction over 24 to 48 hours."@en ;
    rdfs:subClassOf ht:HypertensiveCrisis ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:HypertensiveCrisis
        [ a owl:Restriction ; owl:onProperty ht:hasTargetOrganDamage ;
          owl:maxQualifiedCardinality "0"^^xsd:nonNegativeInteger ; owl:onClass ht:TargetOrganDamage ]
    ) ] .

ht:HypertensiveEmergency a owl:Class ;
    rdfs:label "Hypertensive Emergency"@en ;
    skos:definition "A hypertensive crisis accompanied by acute hypertension-mediated organ damage, representing a life-threatening condition requiring immediate, controlled parenteral blood pressure reduction."@en ;
    rdfs:subClassOf ht:HypertensiveCrisis ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:HypertensiveCrisis
        [ a owl:Restriction ; owl:onProperty ht:hasTargetOrganDamage ; owl:someValuesFrom ht:TargetOrganDamage ]
    ) ] .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveUrgency ht:HypertensiveEmergency ) ] .

#################################################################
# 3. SECONDARY CAUSES
#################################################################

ht:SecondaryCause a owl:Class ;
    rdfs:label "Secondary Cause"@en ;
    skos:definition "An identifiable underlying condition, medication, or substance responsible for secondary hypertension."@en .

ht:hasSecondaryCause a owl:ObjectProperty ;
    rdfs:label "has secondary cause"@en ;
    skos:definition "Relates a case of secondary hypertension to its identifiable underlying cause."@en ;
    rdfs:domain ht:SecondaryHypertension ;
    rdfs:range ht:SecondaryCause .

ht:isSecondaryCauseOf a owl:ObjectProperty ;
    rdfs:label "is secondary cause of"@en ;
    skos:definition "Relates an identifiable underlying cause to the secondary hypertension it produces."@en ;
    owl:inverseOf ht:hasSecondaryCause ;
    rdfs:domain ht:SecondaryCause ;
    rdfs:range ht:SecondaryHypertension .

ht:RenalCause a owl:Class ;
    rdfs:label "Renal Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from kidney disease, the most common category of secondary hypertension cause."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:RenalParenchymalDisease a owl:Class ;
    rdfs:label "Renal Parenchymal Disease"@en ;
    skos:definition "Kidney tissue disease causing hypertension, encompassing diabetic nephropathy, glomerulonephritis, interstitial disorders, polycystic kidney disease, and lupus nephritis."@en ;
    rdfs:subClassOf ht:RenalCause .

ht:RenovascularDisease a owl:Class ;
    rdfs:label "Renovascular Disease"@en ;
    skos:altLabel "Renovascular Hypertension"@en ;
    skos:definition "Hypertension produced by narrowing or obstruction of a renal artery."@en ;
    rdfs:subClassOf ht:RenalCause .

ht:RenalArteryStenosis a owl:Class ;
    rdfs:label "Renal Artery Stenosis"@en ;
    skos:definition "Atherosclerotic or fibromuscular narrowing of the renal artery, a recognized cause of renovascular and isolated systolic hypertension."@en ;
    rdfs:subClassOf ht:RenovascularDisease .

owl:AllDisjointClasses [ owl:members ( ht:RenalParenchymalDisease ht:RenovascularDisease ) ] .

ht:EndocrineCause a owl:Class ;
    rdfs:label "Endocrine Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from a hormonal or endocrine gland disorder."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:PrimaryAldosteronism a owl:Class ;
    rdfs:label "Primary Aldosteronism"@en ;
    skos:altLabel "Conn's Syndrome"@en , "Hyperaldosteronism"@en ;
    skos:definition "Autonomous overproduction of aldosterone by the adrenal glands, due to an aldosterone-producing adenoma or bilateral adrenal hyperplasia, accounting for most endocrine secondary hypertension and present in up to one in five patients with resistant hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:Pheochromocytoma a owl:Class ;
    rdfs:label "Pheochromocytoma"@en ;
    skos:definition "A tumor causing excessive secretion of norepinephrine and epinephrine, promoting vasoconstriction and raising blood pressure."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:CushingSyndrome a owl:Class ;
    rdfs:label "Cushing Syndrome"@en ;
    skos:definition "Hypertension caused by excess glucocorticoid secretion or exposure."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:ThyroidDisease a owl:Class ;
    rdfs:label "Thyroid Disease"@en ;
    skos:definition "Hyperthyroidism or hypothyroidism causing or contributing to secondary hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:PrimaryHyperparathyroidism a owl:Class ;
    rdfs:label "Primary Hyperparathyroidism"@en ;
    skos:definition "Excess parathyroid hormone secretion recognized as a contributor to secondary hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryAldosteronism ht:Pheochromocytoma ht:CushingSyndrome ht:ThyroidDisease ht:PrimaryHyperparathyroidism ) ] .

ht:VascularCause a owl:Class ;
    rdfs:label "Vascular Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from a structural vascular abnormality."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:AorticCoarctation a owl:Class ;
    rdfs:label "Aortic Coarctation"@en ;
    skos:altLabel "Coarctation of the Aorta"@en ;
    skos:definition "A congenital narrowing of the aorta that typically affects younger patients and causes secondary hypertension."@en ;
    rdfs:subClassOf ht:VascularCause .

ht:ObstructiveSleepApnea a owl:Class ;
    rdfs:label "Obstructive Sleep Apnea"@en ;
    skos:altLabel "OSA"@en ;
    skos:definition "A sleep-breathing disorder that is one of the most common causes of secondary hypertension and is also common among patients with resistant hypertension."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:DrugInducedCause a owl:Class ;
    rdfs:label "Drug Induced Cause"@en ;
    skos:altLabel "Drug-Induced Hypertension"@en ;
    skos:definition "A secondary cause of hypertension arising from medications or substances, including NSAIDs, sympathomimetic decongestants, stimulants, corticosteroids, oral contraceptives, cyclosporine, licorice, cocaine, and methamphetamine."@en ;
    rdfs:subClassOf ht:SecondaryCause .

owl:AllDisjointClasses [ owl:members ( ht:RenalCause ht:EndocrineCause ht:VascularCause ht:ObstructiveSleepApnea ht:DrugInducedCause ) ] .

#################################################################
# 4. TARGET ORGAN DAMAGE
#################################################################

ht:TargetOrganDamage a owl:Class ;
    rdfs:label "Target Organ Damage"@en ;
    skos:altLabel "Hypertension-Mediated Organ Damage"@en ;
    skos:definition "Structural or functional injury to the heart, kidneys, brain, or eyes resulting from chronic or acute hypertension."@en .

ht:hasTargetOrganDamage a owl:ObjectProperty ;
    rdfs:label "has target organ damage"@en ;
    skos:definition "Relates a case of hypertension to a form of target-organ damage it has produced."@en ;
    rdfs:domain ht:Hypertension ;
    rdfs:range ht:TargetOrganDamage .

ht:isTargetOrganDamageOf a owl:ObjectProperty ;
    rdfs:label "is target organ damage of"@en ;
    skos:definition "Relates a form of target-organ damage to the hypertension that produced it."@en ;
    owl:inverseOf ht:hasTargetOrganDamage ;
    rdfs:domain ht:TargetOrganDamage ;
    rdfs:range ht:Hypertension .

ht:HypertensiveHeartDisease a owl:Class ;
    rdfs:label "Hypertensive Heart Disease"@en ;
    skos:definition "A constellation of structural and functional changes in the left ventricle, left atrium, and coronary arteries resulting from chronic blood pressure elevation, including remodeling, coronary microvascular dysfunction, and progression to heart failure."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:LeftVentricularHypertrophy a owl:Class ;
    rdfs:label "Left Ventricular Hypertrophy"@en ;
    skos:altLabel "LVH"@en ;
    skos:definition "Thickening of the left ventricular wall in response to chronic pressure overload, the hallmark structural manifestation of hypertensive heart disease."@en ;
    rdfs:subClassOf ht:HypertensiveHeartDisease .

ht:HypertensiveRetinopathy a owl:Class ;
    rdfs:label "Hypertensive Retinopathy"@en ;
    skos:definition "Damage to the retina and retinal circulation due to sustained or abrupt elevations in blood pressure, visible on ophthalmoscopy and correlating with the severity and chronicity of hypertension."@en ;
    rdfs:subClassOf ht:TargetOrganDamage ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:TargetOrganDamage
        [ a owl:Restriction ; owl:onProperty ht:hasRetinalFinding ; owl:someValuesFrom ht:RetinalFinding ]
    ) ] .

ht:HypertensiveNephropathy a owl:Class ;
    rdfs:label "Hypertensive Nephropathy"@en ;
    skos:altLabel "Hypertensive Kidney Disease"@en ;
    skos:definition "Kidney failure or declining renal function attributable to a history of hypertension, a serious risk factor for end-stage kidney disease, underpinned by nephrosclerosis."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:Nephrosclerosis a owl:Class ;
    rdfs:label "Nephrosclerosis"@en ;
    skos:definition "Hardening and thickening of the small blood vessels, glomeruli, tubules, and interstitial tissue of the kidney caused by chronic hypertension, reducing blood and oxygen supply and causing ischemia; the characteristic lesion of hypertensive nephropathy."@en ;
    rdfs:subClassOf ht:HypertensiveNephropathy .

ht:HypertensiveEncephalopathy a owl:Class ;
    rdfs:label "Hypertensive Encephalopathy"@en ;
    skos:definition "Brain swelling and dysfunction caused by severely elevated blood pressure, presenting with headache, confusion, or visual disturbance, and a recognized manifestation of hypertensive emergency."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveHeartDisease ht:HypertensiveRetinopathy ht:HypertensiveNephropathy ht:HypertensiveEncephalopathy ) ] .

ht:RetinalFinding a owl:Class ;
    rdfs:label "Retinal Finding"@en ;
    skos:definition "A specific abnormality of the retinal vessels or retina observed on fundoscopic examination in hypertensive retinopathy."@en .

ht:hasRetinalFinding a owl:ObjectProperty ;
    rdfs:label "has retinal finding"@en ;
    skos:definition "Relates hypertensive retinopathy to a specific retinal abnormality it comprises."@en ;
    rdfs:domain ht:HypertensiveRetinopathy ;
    rdfs:range ht:RetinalFinding .

ht:ArteriolarNarrowing a owl:Class ;
    rdfs:label "Arteriolar Narrowing"@en ;
    skos:definition "Generalized or focal narrowing of the retinal arterioles, an early sign of hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:ArteriovenousNicking a owl:Class ;
    rdfs:label "Arteriovenous Nicking"@en ;
    skos:altLabel "AV Nicking"@en , "AV Nipping"@en ;
    skos:definition "Compression of a retinal vein where it is crossed by a sclerotic arteriole, a sign of hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:RetinalHemorrhage a owl:Class ;
    rdfs:label "Retinal Hemorrhage"@en ;
    skos:altLabel "Flame Hemorrhage"@en , "Blot Hemorrhage"@en ;
    skos:definition "Bleeding into the retinal tissue resulting from breakdown of the blood-retinal barrier in advanced hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:CottonWoolSpot a owl:Class ;
    rdfs:label "Cotton Wool Spot"@en ;
    skos:definition "An ischemic retinal lesion appearing as a pale, fluffy patch, seen in advanced hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:HardExudate a owl:Class ;
    rdfs:label "Hard Exudate"@en ;
    skos:definition "A lipid deposit in the retina resulting from leakage through damaged retinal vessels in hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:Papilledema a owl:Class ;
    rdfs:label "Papilledema"@en ;
    skos:altLabel "Optic Disc Edema"@en ;
    skos:definition "Swelling of the optic disc, the most severe retinal finding, indicating malignant hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

owl:AllDisjointClasses [ owl:members ( ht:ArteriolarNarrowing ht:ArteriovenousNicking ht:RetinalHemorrhage ht:CottonWoolSpot ht:HardExudate ht:Papilledema ) ] .

#################################################################
# 5. ANTIHYPERTENSIVE DRUG CLASSES
#################################################################

ht:Antihypertensive a owl:Class ;
    rdfs:label "Antihypertensive"@en ;
    skos:definition "A class of medication used to lower blood pressure."@en .

ht:hasAntihypertensive a owl:ObjectProperty ;
    rdfs:label "has antihypertensive"@en ;
    skos:definition "Relates a case of hypertension to an antihypertensive drug class used in its treatment."@en ;
    rdfs:domain ht:Hypertension ;
    rdfs:range ht:Antihypertensive .

ht:ThiazideDiuretic a owl:Class ;
    rdfs:label "Thiazide Diuretic"@en ;
    skos:altLabel "Thiazide-type Diuretic"@en ;
    skos:definition "A first-line antihypertensive drug class that blocks sodium reabsorption in the distal convoluted tubule, promoting natriuresis, diuresis, and modest vasodilation; chlorthalidone and indapamide are often preferred over hydrochlorothiazide."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:AngiotensinConvertingEnzymeInhibitor a owl:Class ;
    rdfs:label "Angiotensin Converting Enzyme Inhibitor"@en ;
    skos:altLabel "ACE Inhibitor"@en , "ACEI"@en ;
    skos:definition "A first-line antihypertensive drug class that inhibits the angiotensin-converting enzyme, reducing angiotensin II production and increasing bradykinin levels, thereby causing vasodilation; favored in diabetes, chronic kidney disease, and heart failure, but contraindicated in pregnancy."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:AngiotensinReceptorBlocker a owl:Class ;
    rdfs:label "Angiotensin Receptor Blocker"@en ;
    skos:altLabel "ARB"@en ;
    skos:definition "A first-line antihypertensive drug class that blocks the binding of angiotensin II to the AT1 receptor, producing effects similar to ACE inhibitors with less cough and angioedema; generally not combined with ACE inhibitors."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:CalciumChannelBlocker a owl:Class ;
    rdfs:label "Calcium Channel Blocker"@en ;
    skos:altLabel "CCB"@en ;
    skos:definition "A first-line antihypertensive drug class that inhibits calcium entry through L-type voltage-gated channels in cardiac and vascular smooth muscle."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:Dihydropyridine a owl:Class ;
    rdfs:label "Dihydropyridine"@en ;
    skos:definition "A subtype of calcium channel blocker that acts predominantly on vascular smooth muscle to cause peripheral vasodilation, preferred for treatment of hypertension."@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker .

ht:NonDihydropyridine a owl:Class ;
    rdfs:label "Non Dihydropyridine"@en ;
    skos:definition "A subtype of calcium channel blocker, such as verapamil and diltiazem, that primarily affects cardiac contractility and atrioventricular conduction and is used for arrhythmia management."@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker .

owl:AllDisjointClasses [ owl:members ( ht:Dihydropyridine ht:NonDihydropyridine ) ] .

ht:BetaBlocker a owl:Class ;
    rdfs:label "Beta Blocker"@en ;
    skos:definition "A drug class that inhibits catecholamine binding to beta-adrenergic receptors, reducing heart rate, contractility, and renin release; no longer recommended as first-line therapy for uncomplicated hypertension except with a compelling cardiac indication."@en ;
    rdfs:subClassOf ht:Antihypertensive .

owl:AllDisjointClasses [ owl:members ( ht:ThiazideDiuretic ht:AngiotensinConvertingEnzymeInhibitor ht:AngiotensinReceptorBlocker ht:CalciumChannelBlocker ht:BetaBlocker ) ] .

#################################################################
# 6. RISK FACTORS
#################################################################

ht:RiskFactor a owl:Class ;
    rdfs:label "Risk Factor"@en ;
    skos:definition "A factor, modifiable or non-modifiable, that increases the risk of developing hypertension."@en .

ht:hasRiskFactor a owl:ObjectProperty ;
    rdfs:label "has risk factor"@en ;
    skos:definition "Relates hypertension to a factor contributing to its risk of development."@en ;
    rdfs:domain ht:Hypertension ;
    rdfs:range ht:RiskFactor .

ht:ModifiableRiskFactor a owl:Class ;
    rdfs:label "Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that can be changed through behavior or treatment, such as diet, weight, smoking, exercise, or alcohol intake."@en ;
    rdfs:subClassOf ht:RiskFactor .

ht:ExcessiveSaltIntake a owl:Class ;
    rdfs:label "Excessive Salt Intake"@en ;
    skos:definition "Elevated dietary sodium intake, recognized as a central modifiable risk factor for hypertension, with 50-60% of hypertensive patients demonstrating salt-sensitive physiology."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:Obesity a owl:Class ;
    rdfs:label "Obesity"@en ;
    skos:definition "Excess body weight, a modifiable risk factor whose reduction can lower systolic blood pressure by 5 to 20 mmHg."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:PhysicalInactivity a owl:Class ;
    rdfs:label "Physical Inactivity"@en ;
    skos:definition "Lack of regular exercise, a modifiable risk factor for the development of hypertension."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:TobaccoUse a owl:Class ;
    rdfs:label "Tobacco Use"@en ;
    skos:definition "Smoking or other tobacco consumption, a modifiable risk factor for hypertension."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:ExcessiveAlcoholConsumption a owl:Class ;
    rdfs:label "Excessive Alcohol Consumption"@en ;
    skos:definition "Increased alcohol intake, associated with higher blood pressure and classified as a modifiable risk factor."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:NonModifiableRiskFactor a owl:Class ;
    rdfs:label "Non Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that cannot be changed, such as age, sex, race, family history, or genetics."@en ;
    rdfs:subClassOf ht:RiskFactor .

ht:AdvancedAge a owl:Class ;
    rdfs:label "Advanced Age"@en ;
    skos:definition "Increasing age, a non-modifiable risk factor associated with hypertension prevalence rising to approximately 60% of individuals above age 60."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:FamilyHistoryOfHypertension a owl:Class ;
    rdfs:label "Family History Of Hypertension"@en ;
    skos:definition "A hereditary pattern of hypertension in close relatives, a non-modifiable risk factor reflecting genetic predisposition."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:GeneticPredisposition a owl:Class ;
    rdfs:label "Genetic Predisposition"@en ;
    skos:definition "Inherited genetic variants, more than 2000 of which have been identified with small individual effects on blood pressure, contributing to non-modifiable hypertension risk."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:Race a owl:Class ;
    rdfs:label "Race"@en ;
    skos:definition "A non-modifiable demographic factor influencing hypertension risk and first-line treatment selection, with guidelines recommending different initial drug choices for Black and non-Black populations."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

owl:AllDisjointClasses [ owl:members ( ht:ModifiableRiskFactor ht:NonModifiableRiskFactor ) ] .

#################################################################
# 7. MEASUREMENT METHODS
#################################################################

ht:BloodPressureMeasurementMethod a owl:Class ;
    rdfs:label "Blood Pressure Measurement Method"@en ;
    skos:definition "A technique or setting used to obtain a blood pressure reading."@en .

ht:AuscultatoryMethod a owl:Class ;
    rdfs:label "Auscultatory Method"@en ;
    skos:definition "Blood pressure measurement using a stethoscope and sphygmomanometer, detecting Korotkoff sounds to determine systolic and diastolic pressure."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

ht:OscillometricMethod a owl:Class ;
    rdfs:label "Oscillometric Method"@en ;
    skos:definition "Automated blood pressure measurement that calculates systolic, diastolic, and mean arterial pressures from oscillations in cuff pressure, requiring less operator skill than auscultation."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

ht:OfficeBloodPressureMeasurement a owl:Class ;
    rdfs:label "Office Blood Pressure Measurement"@en ;
    skos:definition "Blood pressure measurement taken in a clinical setting, the conventional entry point for hypertension diagnosis, subject to the white coat effect."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

ht:AmbulatoryBloodPressureMonitoring a owl:Class ;
    rdfs:label "Ambulatory Blood Pressure Monitoring"@en ;
    skos:altLabel "ABPM"@en ;
    skos:definition "Measurement of blood pressure at regular intervals over a full 24-hour sleep-wake cycle, the reference standard for distinguishing white coat and masked hypertension."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

ht:HomeBloodPressureMonitoring a owl:Class ;
    rdfs:label "Home Blood Pressure Monitoring"@en ;
    skos:altLabel "HBPM"@en ;
    skos:definition "Patient self-measurement of blood pressure outside the clinical setting under standardized conditions, found to be as accurate as 24-hour ambulatory monitoring."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

owl:AllDisjointClasses [ owl:members ( ht:AuscultatoryMethod ht:OscillometricMethod ht:OfficeBloodPressureMeasurement ht:AmbulatoryBloodPressureMonitoring ht:HomeBloodPressureMonitoring ) ] .

#################################################################
# 8. TOP-LEVEL KIND DISJOINTNESS
#################################################################

owl:AllDisjointClasses [ owl:members (
    ht:BloodPressureReading
    ht:Hypertension
    ht:Antihypertensive
    ht:SecondaryCause
    ht:TargetOrganDamage
    ht:RiskFactor
    ht:RetinalFinding
    ht:BloodPressureMeasurementMethod
) ] .
