```turtle
@prefix ht:   <http://example.org/onto/hypertension#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/hypertension> a owl:Ontology ;
    rdfs:label "Hypertension Ontology"@en ;
    rdfs:comment "An ontology modeling the classification, etiology, measurement, risk-factor, target-organ-damage, and treatment domain of hypertension, derived from clinical corpus passages."@en .

###############################################################################
# TOP-LEVEL KINDS
###############################################################################

ht:BloodPressureReading a owl:Class ;
    rdfs:label "Blood Pressure Reading"@en ;
    skos:definition "A measured pair of systolic and diastolic values obtained at a point in time."@en ;
    rdfs:subClassOf
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] ,
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] .

ht:Hypertension a owl:Class ;
    rdfs:label "Hypertension"@en ;
    skos:altLabel "High Blood Pressure"@en ;
    skos:definition "A chronic medical condition characterized by persistently elevated arterial blood pressure, diagnosed from repeated measurement rather than symptoms."@en ;
    rdfs:comment "A real guideline conflict exists over the diagnostic systolic threshold: the 2017 ACC/AHA guideline diagnoses hypertension at a systolic pressure of 130 mmHg or more and/or diastolic above 80 mmHg, whereas ESC/ESH, JNC 7, the World Health Organization and the 2020 ISH guideline retain a threshold of 140/90 mmHg. This is modeled honestly with a single functional property rather than per-guideline subclasses."@en .

ht:Antihypertensive a owl:Class ;
    rdfs:label "Antihypertensive"@en ;
    skos:definition "A class of medication used to lower blood pressure in the treatment of hypertension."@en .

ht:SecondaryCause a owl:Class ;
    rdfs:label "Secondary Cause"@en ;
    skos:definition "An identifiable underlying medical condition, vascular abnormality, or substance responsible for elevated blood pressure in secondary hypertension."@en .

ht:TargetOrganDamage a owl:Class ;
    rdfs:label "Target Organ Damage"@en ;
    skos:altLabel "Hypertension-Mediated Organ Damage"@en ;
    skos:definition "Structural or functional injury to the heart, retina, kidney, or brain resulting from chronic or acute hypertension."@en .

ht:RiskFactor a owl:Class ;
    rdfs:label "Risk Factor"@en ;
    skos:definition "A modifiable or non-modifiable factor that increases the likelihood of developing hypertension."@en .

ht:RetinalFinding a owl:Class ;
    rdfs:label "Retinal Finding"@en ;
    skos:definition "A named abnormality of the retinal vasculature or retinal tissue observed on fundoscopic examination in hypertensive retinopathy."@en .

ht:BloodPressureMeasurementMethod a owl:Class ;
    rdfs:label "Blood Pressure Measurement Method"@en ;
    skos:definition "A technique or setting used to obtain a blood pressure reading."@en .

owl:AllDisjointClasses [ owl:members (
    ht:BloodPressureReading ht:Hypertension ht:Antihypertensive ht:SecondaryCause
    ht:TargetOrganDamage ht:RiskFactor ht:RetinalFinding ht:BloodPressureMeasurementMethod
) ] .

###############################################################################
# BLOOD PRESSURE CATEGORY (ACC/AHA 2017)
###############################################################################

ht:BloodPressureCategory a owl:Class ;
    rdfs:label "Blood Pressure Category"@en ;
    skos:definition "One of the ACC/AHA 2017 classification bands assigned to a blood pressure reading on the basis of its systolic and/or diastolic value."@en ;
    rdfs:comment "This ontology models the single 2017 ACC/AHA four-band scheme. Competing schemes exist: ESC/ESH (2018/2023) use optimal/normal/high-normal/grade 1-3 with a 140/90 mmHg diagnostic threshold; JNC 7 uses normal/prehypertension/stage 1 (140-159/90-99)/stage 2 (>=160/100); NICE NG136 adds clinic-vs-ABPM/HBPM dual thresholds and a stage 3 (severe) band; the 2020 ISH guideline uses normal/high-normal/grade 1/grade 2 with a 140/90 mmHg threshold. These are noted here rather than modeled as parallel class trees."@en .

ht:NormalBloodPressure a owl:Class ;
    rdfs:label "Normal Blood Pressure"@en ;
    skos:definition "A blood pressure reading with systolic pressure less than 120 mmHg and diastolic pressure less than 80 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 120 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ]
    ) ] .

ht:ElevatedBloodPressure a owl:Class ;
    rdfs:label "Elevated Blood Pressure"@en ;
    skos:altLabel "Prehypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 120 to 129 mmHg and diastolic pressure less than 80 mmHg; this category replaced part of the former prehypertension range under the 2017 ACC/AHA guideline."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:minInclusive 120 ] [ xsd:maxInclusive 129 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ]
    ) ] .

ht:Stage1Hypertension a owl:Class ;
    rdfs:label "Stage 1 Hypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 130 to 139 mmHg or diastolic pressure of 80 to 89 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    rdfs:comment "ESC/ESH classify this same numeric range as 'high-normal' (130-139/85-89), not as hypertension; JNC 7 classifies 120-139/80-89 as 'prehypertension'."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:BloodPressureReading
        [ a owl:Class ; owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 130 ] [ xsd:maxInclusive 139 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 80 ] [ xsd:maxInclusive 89 ] ) ] ]
        ) ]
    ) ] .

ht:Stage2Hypertension a owl:Class ;
    rdfs:label "Stage 2 Hypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 140 mmHg or greater or diastolic pressure of 90 mmHg or greater."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    rdfs:comment "ESC/ESH subdivide this range into grades 1, 2 and 3; JNC 7 labels 140-159/90-99 as stage 1 and >=160/100 as stage 2."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:BloodPressureReading
        [ a owl:Class ; owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 140 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 90 ] ) ] ]
        ) ]
    ) ] .

owl:AllDisjointClasses [ owl:members (
    ht:NormalBloodPressure ht:ElevatedBloodPressure ht:Stage1Hypertension ht:Stage2Hypertension
) ] .

###############################################################################
# HYPERTENSION TYPES (ETIOLOGY)
###############################################################################

ht:PrimaryHypertension a owl:Class ;
    rdfs:label "Primary Hypertension"@en ;
    skos:altLabel "Essential Hypertension"@en , "Idiopathic Hypertension"@en ;
    skos:definition "Hypertension with no single identifiable cause, arising from a complex interaction of genetic predisposition and environmental factors such as dietary sodium, obesity, and physical inactivity; it accounts for approximately 85-95% of cases."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:SecondaryHypertension a owl:Class ;
    rdfs:label "Secondary Hypertension"@en ;
    skos:altLabel "Inessential Hypertension"@en ;
    skos:definition "Hypertension that results from a specific, identifiable, and often treatable or reversible underlying cause; it accounts for approximately 5-15% of adult cases, with prevalence much higher in children and lower in older adults."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasSecondaryCause ; owl:someValuesFrom ht:SecondaryCause ]
    ) ] .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryHypertension ht:SecondaryHypertension ) ] .

ht:IsolatedSystolicHypertension a owl:Class ;
    rdfs:label "Isolated Systolic Hypertension"@en ;
    skos:definition "Hypertension in which systolic blood pressure is elevated (traditionally above 140 mmHg, or 130 mmHg under the 2017 ACC/AHA threshold) with a preserved or low diastolic pressure below 90 mmHg, producing a widened pulse pressure; it is the predominant form of hypertension in older adults and chiefly results from age-related arterial stiffening."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:WhiteCoatHypertension a owl:Class ;
    rdfs:label "White Coat Hypertension"@en ;
    skos:altLabel "WHT"@en , "White Coat Syndrome"@en , "White Coat Effect"@en ;
    skos:definition "A form of labile hypertension in which office blood pressure is consistently elevated but out-of-office blood pressure is normal, believed to reflect anxiety associated with the clinical setting."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:MaskedHypertension a owl:Class ;
    rdfs:label "Masked Hypertension"@en ;
    skos:altLabel "MH"@en ;
    skos:definition "A blood pressure phenotype in which office blood pressure is normal but out-of-office blood pressure, measured by ambulatory or home monitoring, is elevated; it carries cardiovascular risk approaching that of sustained hypertension."@en ;
    rdfs:subClassOf ht:Hypertension .

owl:AllDisjointClasses [ owl:members ( ht:WhiteCoatHypertension ht:MaskedHypertension ) ] .

ht:ResistantHypertension a owl:Class ;
    rdfs:label "Resistant Hypertension"@en ;
    skos:definition "Blood pressure that remains uncontrolled to goal despite adherence to three suitably dosed antihypertensive medications of different classes, one of which is a diuretic, or blood pressure requiring four or more agents, after exclusion of the white-coat effect and confirmation of adherence."@en ;
    rdfs:subClassOf ht:Hypertension ,
        [ a owl:Restriction ; owl:onProperty ht:hasAntihypertensive ;
          owl:minQualifiedCardinality 3 ; owl:onClass ht:Antihypertensive ] .

ht:HypertensiveCrisis a owl:Class ;
    rdfs:label "Hypertensive Crisis"@en ;
    skos:definition "A severe, acute elevation of blood pressure, commonly defined as systolic pressure of 180 mmHg or more or diastolic pressure of 120 mmHg or more, classified according to the presence or absence of acute target-organ damage."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:HypertensiveUrgency a owl:Class ;
    rdfs:label "Hypertensive Urgency"@en ;
    skos:definition "A hypertensive crisis without evidence of acute target-organ damage, managed with gradual oral blood pressure reduction over 24 to 48 hours."@en ;
    rdfs:subClassOf ht:HypertensiveCrisis .

ht:HypertensiveEmergency a owl:Class ;
    rdfs:label "Hypertensive Emergency"@en ;
    skos:definition "A hypertensive crisis accompanied by acute hypertension-mediated target-organ damage, representing a life-threatening condition requiring immediate, controlled, typically intravenous blood pressure reduction."@en ;
    rdfs:subClassOf ht:HypertensiveCrisis ,
        [ a owl:Restriction ; owl:onProperty ht:hasTargetOrganDamage ; owl:someValuesFrom ht:TargetOrganDamage ] .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveUrgency ht:HypertensiveEmergency ) ] .

###############################################################################
# SECONDARY CAUSES
###############################################################################

ht:RenalCause a owl:Class ;
    rdfs:label "Renal Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from disease of the kidney or its vasculature; renal causes are the most common group of secondary causes."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:RenalParenchymalDisease a owl:Class ;
    rdfs:label "Renal Parenchymal Disease"@en ;
    skos:definition "Disease of the kidney tissue itself, including diabetic nephropathy, glomerulonephritis, interstitial disorders, and polycystic kidney disease, that causes secondary hypertension."@en ;
    rdfs:subClassOf ht:RenalCause .

ht:RenovascularDisease a owl:Class ;
    rdfs:label "Renovascular Disease"@en ;
    skos:definition "Disease of the renal artery that produces hypertension through renal artery narrowing."@en ;
    rdfs:subClassOf ht:RenalCause .

ht:RenalArteryStenosis a owl:Class ;
    rdfs:label "Renal Artery Stenosis"@en ;
    skos:definition "Narrowing of the renal artery that produces renovascular hypertension and is also a recognized secondary cause of isolated systolic hypertension."@en ;
    rdfs:subClassOf ht:RenovascularDisease .

owl:AllDisjointClasses [ owl:members ( ht:RenalParenchymalDisease ht:RenovascularDisease ) ] .

ht:EndocrineCause a owl:Class ;
    rdfs:label "Endocrine Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from a hormonal disorder."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:PrimaryAldosteronism a owl:Class ;
    rdfs:label "Primary Aldosteronism"@en ;
    skos:altLabel "Conn's Syndrome"@en ;
    skos:definition "Autonomous overproduction of aldosterone by the adrenal glands, due to an aldosterone-producing adenoma or bilateral adrenal hyperplasia, causing sodium and water retention and hypertension; it accounts for most endocrine secondary causes and is found in as many as one in five patients with resistant hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:Pheochromocytoma a owl:Class ;
    rdfs:label "Pheochromocytoma"@en ;
    skos:definition "A tumor causing excessive secretion of norepinephrine and epinephrine that promotes vasoconstriction and raises blood pressure."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:CushingSyndrome a owl:Class ;
    rdfs:label "Cushing Syndrome"@en ;
    skos:definition "An endocrine disorder of excess glucocorticoids that is a recognized secondary cause of hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:Hyperthyroidism a owl:Class ;
    rdfs:label "Hyperthyroidism"@en ;
    skos:definition "Excess thyroid hormone production, recognized as a secondary cause of hypertension and of isolated systolic hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:Hypothyroidism a owl:Class ;
    rdfs:label "Hypothyroidism"@en ;
    skos:definition "Deficient thyroid hormone production, recognized as a secondary cause of hypertension and of isolated systolic hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:PrimaryHyperparathyroidism a owl:Class ;
    rdfs:label "Primary Hyperparathyroidism"@en ;
    skos:definition "Excess parathyroid hormone secretion recognized as a contributor to secondary hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

owl:AllDisjointClasses [ owl:members (
    ht:PrimaryAldosteronism ht:Pheochromocytoma ht:CushingSyndrome
    ht:Hyperthyroidism ht:Hypothyroidism ht:PrimaryHyperparathyroidism
) ] .

ht:VascularCause a owl:Class ;
    rdfs:label "Vascular Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from a structural abnormality of the great vessels."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:AorticCoarctation a owl:Class ;
    rdfs:label "Aortic Coarctation"@en ;
    skos:altLabel "Coarctation of the Aorta"@en ;
    skos:definition "A congenital narrowing of the aorta that typically affects younger patients and is a recognized secondary cause of hypertension."@en ;
    rdfs:subClassOf ht:VascularCause .

ht:ObstructiveSleepApnea a owl:Class ;
    rdfs:label "Obstructive Sleep Apnea"@en ;
    skos:altLabel "OSA"@en ;
    skos:definition "A sleep-related breathing disorder that is one of the most common secondary causes of hypertension and of resistant hypertension."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:DrugInducedCause a owl:Class ;
    rdfs:label "Drug Induced Cause"@en ;
    skos:altLabel "Drug-Induced Hypertension"@en ;
    skos:definition "Elevated blood pressure caused by a medication or substance, including NSAIDs, sympathomimetic decongestants, stimulants, corticosteroids, oral contraceptives, cyclosporine, licorice, and recreational substances such as cocaine and methamphetamine; discontinuation of the offending agent may resolve the hypertension."@en ;
    rdfs:subClassOf ht:SecondaryCause .

owl:AllDisjointClasses [ owl:members (
    ht:RenalCause ht:EndocrineCause ht:VascularCause ht:ObstructiveSleepApnea ht:DrugInducedCause
) ] .

###############################################################################
# TARGET ORGAN DAMAGE
###############################################################################

ht:HypertensiveHeartDisease a owl:Class ;
    rdfs:label "Hypertensive Heart Disease"@en ;
    skos:definition "Structural and functional changes in the left ventricle, left atrium, and coronary arteries resulting from chronic blood pressure elevation, including compensatory remodeling, myocyte apoptosis, interstitial fibrosis, and eventual heart failure."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:LeftVentricularHypertrophy a owl:Class ;
    rdfs:label "Left Ventricular Hypertrophy"@en ;
    skos:definition "Thickening of the left ventricular wall in response to chronic pressure overload; the hallmark structural manifestation of hypertensive cardiac target-organ damage and a strong predictor of cardiovascular events."@en ;
    rdfs:subClassOf ht:HypertensiveHeartDisease .

ht:HypertensiveRetinopathy a owl:Class ;
    rdfs:label "Hypertensive Retinopathy"@en ;
    skos:definition "Damage to the retina and retinal circulation due to sustained or abrupt elevations in blood pressure, visible directly on fundoscopic examination and correlating with the severity and chronicity of systemic hypertension."@en ;
    rdfs:subClassOf ht:TargetOrganDamage ,
        [ a owl:Restriction ; owl:onProperty ht:hasRetinalFinding ; owl:someValuesFrom ht:RetinalFinding ] .

ht:HypertensiveNephropathy a owl:Class ;
    rdfs:label "Hypertensive Nephropathy"@en ;
    skos:altLabel "Hypertensive Kidney Disease"@en ;
    skos:definition "Kidney damage and progressive decline in renal function attributable to chronic hypertension, with the characteristic lesion of nephrosclerosis, a hardening and thickening of small renal vessels, glomeruli, tubules and interstitial tissue that reduces blood and oxygen supply and can progress to end-stage kidney disease."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:HypertensiveEncephalopathy a owl:Class ;
    rdfs:label "Hypertensive Encephalopathy"@en ;
    skos:definition "Brain swelling and dysfunction caused by severely elevated blood pressure, presenting with headache, confusion, or visual disturbance, and a recognized manifestation of hypertensive emergency."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

owl:AllDisjointClasses [ owl:members (
    ht:HypertensiveHeartDisease ht:HypertensiveRetinopathy ht:HypertensiveNephropathy ht:HypertensiveEncephalopathy
) ] .

###############################################################################
# RETINAL FINDINGS
###############################################################################

ht:ArteriolarNarrowing a owl:Class ;
    rdfs:label "Arteriolar Narrowing"@en ;
    skos:definition "Generalized or focal narrowing of the retinal arterioles, the earliest sign of hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:ArteriovenousNicking a owl:Class ;
    rdfs:label "Arteriovenous Nicking"@en ;
    skos:altLabel "AV Nicking"@en , "AV Nipping"@en ;
    skos:definition "Compression of a retinal vein where it is crossed by a sclerotic arteriole."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:RetinalHemorrhage a owl:Class ;
    rdfs:label "Retinal Hemorrhage"@en ;
    skos:altLabel "Flame Hemorrhage"@en ;
    skos:definition "Bleeding into the retina, including flame-shaped and blot hemorrhages, resulting from breakdown of the blood-retinal barrier in advanced hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:CottonWoolSpot a owl:Class ;
    rdfs:label "Cotton Wool Spot"@en ;
    skos:definition "A whitish, fluffy retinal lesion representing a localized area of retinal ischemia seen in advanced hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:HardExudate a owl:Class ;
    rdfs:label "Hard Exudate"@en ;
    skos:definition "A lipid deposit in the retina resulting from leakage through damaged retinal vessels in hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:Papilledema a owl:Class ;
    rdfs:label "Papilledema"@en ;
    skos:altLabel "Optic Disc Edema"@en ;
    skos:definition "Swelling of the optic disc, the most severe retinal finding of hypertensive retinopathy and a manifestation of malignant hypertension and hypertensive emergency."@en ;
    rdfs:subClassOf ht:RetinalFinding .

owl:AllDisjointClasses [ owl:members (
    ht:ArteriolarNarrowing ht:ArteriovenousNicking ht:RetinalHemorrhage
    ht:CottonWoolSpot ht:HardExudate ht:Papilledema
) ] .

###############################################################################
# ANTIHYPERTENSIVE DRUG CLASSES
###############################################################################

ht:ThiazideDiuretic a owl:Class ;
    rdfs:label "Thiazide Diuretic"@en ;
    skos:altLabel "Thiazide-Type Diuretic"@en ;
    skos:definition "A first-line antihypertensive drug class that blocks sodium reabsorption in the distal convoluted tubule, promoting natriuresis and diuresis and producing modest vasodilation; chlorthalidone and indapamide are preferred alternatives to hydrochlorothiazide."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:AngiotensinConvertingEnzymeInhibitor a owl:Class ;
    rdfs:label "Angiotensin Converting Enzyme Inhibitor"@en ;
    skos:altLabel "ACE Inhibitor"@en , "ACEI"@en ;
    skos:definition "A first-line antihypertensive drug class that inhibits the angiotensin-converting enzyme, reducing angiotensin II production and increasing bradykinin, causing vasodilation; particularly indicated in diabetes, chronic kidney disease, and heart failure, contraindicated in pregnancy, and associated with cough and angioedema."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:AngiotensinReceptorBlocker a owl:Class ;
    rdfs:label "Angiotensin Receptor Blocker"@en ;
    skos:altLabel "ARB"@en , "Angiotensin II Receptor Blocker"@en ;
    skos:definition "A first-line antihypertensive drug class that blocks the binding of angiotensin II to the AT1 receptor rather than affecting its production; effective similarly to ACE inhibitors but with lower rates of cough and angioedema, and generally not combined with ACE inhibitors."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:CalciumChannelBlocker a owl:Class ;
    rdfs:label "Calcium Channel Blocker"@en ;
    skos:altLabel "CCB"@en ;
    skos:definition "A first-line antihypertensive drug class that inhibits calcium entry through L-type voltage-gated calcium channels in cardiac and vascular smooth muscle, lowering blood pressure through vasodilation or reduced cardiac contractility."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:DihydropyridineCalciumChannelBlocker a owl:Class ;
    rdfs:label "Dihydropyridine Calcium Channel Blocker"@en ;
    skos:definition "A subtype of calcium channel blocker, such as amlodipine or nifedipine, that acts predominantly on vascular smooth muscle to cause peripheral vasodilation and is preferred for treatment of hypertension."@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker .

ht:NonDihydropyridineCalciumChannelBlocker a owl:Class ;
    rdfs:label "Non Dihydropyridine Calcium Channel Blocker"@en ;
    skos:definition "A subtype of calcium channel blocker, such as verapamil or diltiazem, that primarily affects cardiac contractility and atrioventricular conduction and is better suited to managing arrhythmias than hypertension alone."@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker .

owl:AllDisjointClasses [ owl:members ( ht:DihydropyridineCalciumChannelBlocker ht:NonDihydropyridineCalciumChannelBlocker ) ] .

ht:BetaBlocker a owl:Class ;
    rdfs:label "Beta Blocker"@en ;
    skos:definition "An antihypertensive drug class that inhibits catecholamine binding to beta-adrenergic receptors, decreasing heart rate, contractility, and renin release; no longer recommended as first-line therapy for uncomplicated hypertension but preferred when a compelling cardiac indication is present."@en ;
    rdfs:subClassOf ht:Antihypertensive .

owl:AllDisjointClasses [ owl:members (
    ht:ThiazideDiuretic ht:AngiotensinConvertingEnzymeInhibitor ht:AngiotensinReceptorBlocker
    ht:CalciumChannelBlocker ht:BetaBlocker
) ] .

###############################################################################
# RISK FACTORS
###############################################################################

ht:ModifiableRiskFactor a owl:Class ;
    rdfs:label "Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that can be altered through lifestyle or behavioral change."@en ;
    rdfs:subClassOf ht:RiskFactor .

ht:NonModifiableRiskFactor a owl:Class ;
    rdfs:label "Non Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that cannot be altered, such as age, sex, race, or family history."@en ;
    rdfs:subClassOf ht:RiskFactor .

owl:AllDisjointClasses [ owl:members ( ht:ModifiableRiskFactor ht:NonModifiableRiskFactor ) ] .

ht:DietarySaltIntake a owl:Class ;
    rdfs:label "Dietary Salt Intake"@en ;
    skos:definition "Excess dietary sodium consumption, a modifiable risk factor to which approximately 50-60% of hypertensive patients are physiologically sensitive."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:Obesity a owl:Class ;
    rdfs:label "Obesity"@en ;
    skos:definition "Excess body weight, a modifiable risk factor for hypertension; weight reduction alone can lower systolic blood pressure by 5 to 20 mmHg."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:PhysicalInactivity a owl:Class ;
    rdfs:label "Physical Inactivity"@en ;
    skos:definition "Lack of regular exercise, a modifiable risk factor contributing to the development of hypertension."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:TobaccoUse a owl:Class ;
    rdfs:label "Tobacco Use"@en ;
    skos:definition "Smoking or other tobacco consumption, a modifiable risk factor for hypertension."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:AlcoholConsumption a owl:Class ;
    rdfs:label "Alcohol Consumption"@en ;
    skos:definition "Intake of alcohol, which is associated with higher blood pressure and constitutes a modifiable risk factor."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

owl:AllDisjointClasses [ owl:members (
    ht:DietarySaltIntake ht:Obesity ht:PhysicalInactivity ht:TobaccoUse ht:AlcoholConsumption
) ] .

ht:AdvancedAge a owl:Class ;
    rdfs:label "Advanced Age"@en ;
    skos:definition "Increasing age, a non-modifiable risk factor; prevalence of hypertension rises to approximately 60% of individuals above age 60."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:FamilyHistoryOfHypertension a owl:Class ;
    rdfs:label "Family History Of Hypertension"@en ;
    skos:definition "A family history of high blood pressure, a non-modifiable risk factor reflecting genetic predisposition."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:Race a owl:Class ;
    rdfs:label "Race"@en ;
    skos:definition "Racial or ethnic background, a non-modifiable risk factor that also influences first-line treatment selection, for example between Black and non-Black populations."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

owl:AllDisjointClasses [ owl:members ( ht:AdvancedAge ht:FamilyHistoryOfHypertension ht:Race ) ] .

###############################################################################
# MEASUREMENT METHODS
###############################################################################

ht:AuscultatoryMethod a owl:Class ;
    rdfs:label "Auscultatory Method"@en ;
    skos:definition "Blood pressure measurement using a stethoscope and sphygmomanometer, in which systolic pressure is marked by the first Korotkoff sound and diastolic pressure by the disappearance of sound."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

ht:OscillometricMethod a owl:Class ;
    rdfs:label "Oscillometric Method"@en ;
    skos:definition "Blood pressure measurement using an automated device that detects cuff pressure oscillations produced by arterial pulsation, requiring less operator skill than the auscultatory method."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

ht:OfficeBloodPressureMeasurement a owl:Class ;
    rdfs:label "Office Blood Pressure Measurement"@en ;
    skos:definition "Blood pressure measurement taken in a clinical setting, conventionally requiring at least two readings on at least two separate occasions for diagnosis."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

ht:AmbulatoryBloodPressureMonitoring a owl:Class ;
    rdfs:label "Ambulatory Blood Pressure Monitoring"@en ;
    skos:altLabel "ABPM"@en ;
    skos:definition "Out-of-office blood pressure measurement at regular intervals over a full 24-hour sleep-wake cycle, regarded as the reference standard for distinguishing white coat and masked hypertension."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

ht:HomeBloodPressureMonitoring a owl:Class ;
    rdfs:label "Home Blood Pressure Monitoring"@en ;
    skos:altLabel "HBPM"@en ;
    skos:definition "Out-of-office blood pressure self-measurement performed by the patient using a home monitoring device, found to be comparably accurate to 24-hour ambulatory monitoring."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

###############################################################################
# OBJECT PROPERTIES
###############################################################################

ht:hasBloodPressureCategory a owl:ObjectProperty ;
    rdfs:label "has blood pressure category"@en ;
    skos:definition "Relates a blood pressure reading to the ACC/AHA 2017 category it falls within."@en ;
    rdfs:domain ht:BloodPressureReading ;
    rdfs:range ht:BloodPressureCategory .

ht:isBloodPressureCategoryOf a owl:ObjectProperty ;
    rdfs:label "is blood pressure category of"@en ;
    skos:definition "Relates a blood pressure category to a reading it classifies."@en ;
    owl:inverseOf ht:hasBloodPressureCategory ;
    rdfs:domain ht:BloodPressureCategory ;
    rdfs:range ht:BloodPressureReading .

ht:hasSecondaryCause a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has secondary cause"@en ;
    skos:definition "Relates secondary hypertension to its identifiable underlying cause."@en ;
    rdfs:domain ht:SecondaryHypertension ;
    rdfs:range ht:SecondaryCause .

ht:isSecondaryCauseOf a owl:ObjectProperty ;
    rdfs:label "is secondary cause of"@en ;
    skos:definition "Relates an identifiable underlying cause to the secondary hypertension it produces."@en ;
    owl:inverseOf ht:hasSecondaryCause ;
    rdfs:domain ht:SecondaryCause ;
    rdfs:range ht:SecondaryHypertension .

ht:hasAntihypertensive a owl:ObjectProperty ;
    rdfs:label "has antihypertensive"@en ;
    skos:definition "Relates hypertension to an antihypertensive drug class used in its treatment."@en ;
    rdfs:domain ht:Hypertension ;
    rdfs:range ht:Antihypertensive .

ht:isAntihypertensiveOf a owl:ObjectProperty ;
    rdfs:label "is antihypertensive of"@en ;
    skos:definition "Relates an antihypertensive drug class to the hypertension it is used to treat."@en ;
    owl:inverseOf ht:hasAntihypertensive ;
    rdfs:domain ht:Antihypertensive ;
    rdfs:range ht:Hypertension .

ht:hasTargetOrganDamage a owl:ObjectProperty ;
    rdfs:label "has target organ damage"@en ;
    skos:definition "Relates hypertension to target-organ damage it has caused."@en ;
    rdfs:domain ht:Hypertension ;
    rdfs:range ht:TargetOrganDamage .

ht:isTargetOrganDamageOf a owl:ObjectProperty ;
    rdfs:label "is target organ damage of"@en ;
    skos:definition "Relates target-organ damage to the hypertension that caused it."@en ;
    owl:inverseOf ht:hasTargetOrganDamage ;
    rdfs:domain ht:TargetOrganDamage ;
    rdfs:range ht:Hypertension .

ht:hasRiskFactor a owl:ObjectProperty ;
    rdfs:label "has risk factor"@en ;
    skos:definition "Relates hypertension to a factor that increases the likelihood of its development."@en ;
    rdfs:domain ht:Hypertension ;
    rdfs:range ht:RiskFactor .

ht:isRiskFactorOf a owl:ObjectProperty ;
    rdfs:label "is risk factor of"@en ;
    skos:definition "Relates a risk factor to the hypertension whose likelihood it increases."@en ;
    owl:inverseOf ht:hasRiskFactor ;
    rdfs:domain ht:RiskFactor ;
    rdfs:range ht:Hypertension .

ht:hasRetinalFinding a owl:ObjectProperty ;
    rdfs:label "has retinal finding"@en ;
    skos:definition "Relates hypertensive retinopathy to a specific retinal abnormality observed on examination."@en ;
    rdfs:domain ht:HypertensiveRetinopathy ;
    rdfs:range ht:RetinalFinding .

ht:isRetinalFindingOf a owl:ObjectProperty ;
    rdfs:label "is retinal finding of"@en ;
    skos:definition "Relates a retinal abnormality to the hypertensive retinopathy in which it is observed."@en ;
    owl:inverseOf ht:hasRetinalFinding ;
    rdfs:domain ht:RetinalFinding ;
    rdfs:range ht:HypertensiveRetinopathy .

###############################################################################
# DATATYPE PROPERTIES
###############################################################################

ht:hasSystolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has systolic value"@en ;
    skos:definition "The systolic blood pressure value, in mmHg, of a blood pressure reading: the pressure in the arteries when the heart contracts."@en ;
    rdfs:domain ht:BloodPressureReading ;
    rdfs:range xsd:integer .

ht:hasDiastolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diastolic value"@en ;
    skos:definition "The diastolic blood pressure value, in mmHg, of a blood pressure reading: the pressure in the arteries when the heart relaxes between beats."@en ;
    rdfs:domain ht:BloodPressureReading ;
    rdfs:range xsd:integer .

ht:hasDiagnosticSystolicThreshold a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diagnostic systolic threshold"@en ;
    skos:definition "The systolic blood pressure value, in mmHg, at or above which hypertension is diagnosed under a given guideline."@en ;
    rdfs:domain ht:Hypertension ;
    rdfs:range xsd:integer ;
    rdfs:comment "Competing values are documented in the corpus: the 2017 ACC/AHA guideline sets this threshold at 130 mmHg, whereas ESC/ESH (2018, 2023), JNC 7, the World Health Organization, and the 2020 ISH guideline set it at 140 mmHg. Modeled as a single functional property on Hypertension rather than as per-guideline subclasses."@en .
